-- ==========================================
-- BỔ SUNG CÁC CỘT CÒN THIẾU CHO BẢNG PRODUCT
-- ==========================================
ALTER TABLE public.product
ADD COLUMN IF NOT EXISTS origin text,
ADD COLUMN IF NOT EXISTS ingredients text,
ADD COLUMN IF NOT EXISTS benefits text,
ADD COLUMN IF NOT EXISTS usage_instructions text,
ADD COLUMN IF NOT EXISTS specs text,
ADD COLUMN IF NOT EXISTS badge text,
ADD COLUMN IF NOT EXISTS stock integer DEFAULT 0,
ADD COLUMN IF NOT EXISTS rating numeric(3,1) DEFAULT 0.0,
ADD COLUMN IF NOT EXISTS review_count integer DEFAULT 0;

-- ==========================================
-- CẬP NHẬT DỮ LIỆU TỪ CSV
-- ==========================================
UPDATE public.product SET origin = 'Pháp', ingredients = 'Protein gia cầm sấy khô, mỡ động vật, bột bắp, gạo, protein thực vật cô lập, protein động vật thủy phân, men, dầu cá, bột củ cải đường, xơ thực vật, dầu đậu nành, khoáng chất, fructo-oligo-saccharide (0.35%), men thủy phân (nguồn manno-oligo-saccharide), chiết xuất men (nguồn betaglucan), chiết xuất vạn thọ (nguồn lutein).', benefits = 'Cung cấp nguồn dinh dưỡng siêu cao cấp cho mèo mẹ mang thai/cho con bú và mèo con từ 1 đến 4 tháng tuổi. Giúp xây dựng hệ thống miễn dịch tự nhiên của mèo con nhờ phức hợp chất chống oxy hóa bao gồm Vitamin E, C, taurine và lutein. Hỗ trợ tối đa hệ tiêu hóa chưa trưởng thành với các protein dễ tiêu hóa (L.I.P.) và prebiotic.', usage_instructions = 'Cho ăn trực tiếp hoặc ngâm với nước ấm hoặc sữa chuyên dụng cho mèo con trong vòng 10-15 phút để hạt mềm ra trước khi cho ăn. Chia nhỏ khẩu phần thành 3-4 bữa/ngày dựa trên bảng định lượng in trên bao bì theo tuổi và cân nặng của bé. Luôn chuẩn bị sẵn nước sạch.', specs = '', badge = 'best', stock = 45, rating = 4.9, review_count = 128 WHERE id = 'a0000000-0000-0000-0000-000000000001';
UPDATE public.product SET origin = 'Việt Nam', ingredients = 'Cá hồi tươi nguyên chất (30%), thịt ức gà không da (50%), gan gà tươi (10%), thạch agar nhập khẩu từ Nhật Bản (5%), nước sạch và phức hợp vitamin, khoáng chất thiết yếu (Vitamin A, D3, E, Canxi, kẽm, sắt) bảo đảm không chứa chất bảo quan nhân tạo.', benefits = 'Bổ sung hàm lượng Omega 3, 6, DHA và EPA dồi dào từ cá hồi tươi giúp nuôi dưỡng nang lông từ sâu bên trong, mang lại bộ lông bóng mượt và giảm thiểu tình trạng rụng lông. Cung cấp độ ẩm tự nhiên lớn (>80%) giúp hỗ trợ chức năng hệ tiết niệu, hạn chế tối đa nguy cơ sỏi thận và các bệnh đường tiết niệu phổ biến ở chó mèo.', usage_instructions = 'Mở lon và cho ăn trực tiếp hoặc trộn chung với hạt khô để tăng vị giác. Đối với mèo trưởng thành (từ 1-7kg), sử dụng từ 1/4 đến 1 lon mỗi ngày tùy thể trạng. Sau khi mở nắp, bảo quản phần còn lại trong ngăn mát tủ lạnh và sử dụng hết trong vòng 3 ngày. Nên hâm ấm lại trước khi cho ăn.', specs = '', badge = 'hot', stock = 120, rating = 4.8, review_count = 94 WHERE id = 'a0000000-0000-0000-0000-000000000002';
UPDATE public.product SET origin = 'Nhật Bản', ingredients = 'Cá ngừ đại dương tươi ngon (90%), bột cá ngừ, chiết xuất trà xanh kháng khuẩn, vitamin E bảo vệ tế bào, men vi sinh hỗ trợ đường ruột, taurine hỗ trợ thị lực và cơ tim, bột thạch agar.', benefits = 'Dùng làm thức ăn nhẹ kích thích vị giác và tương tác kết nối giữa chủ nuôi và bé cưng. Chiết xuất trà xanh giúp làm giảm đáng kể mùi hôi khó chịu của chất thải và nước tiểu của mèo. Bổ sung nước nhanh chóng giúp ngăn ngừa các vấn đề sỏi tiết niệu do mèo lười uống nước.', usage_instructions = 'Xé gói súp thưởng và cho mèo liếm trực tiếp từ thanh súp, hoặc bóp trộn lên thức ăn chính (hạt, pate) để gia tăng độ hấp dẫn. Khẩu phần khuyến nghị: sử dụng 2-4 thanh/ngày làm bữa phụ. Không dùng thay thế hoàn toàn cho bữa ăn chính.', specs = '', badge = 'new', stock = 3, rating = 4.7, review_count = 256 WHERE id = 'a0000000-0000-0000-0000-000000000003';
UPDATE public.product SET origin = 'Thái Lan', ingredients = 'Ngũ cốc lúa mì nguyên cám, protein động vật (thịt gia cầm, cá biển), dầu thực vật (dầu đậu nành, dầu cọ), chất xơ tự nhiên, khoáng chất thiết yếu (Canxi, Phospho, Kali, Natri), vitamin tổng hợp.', benefits = 'Cung cấp nguồn năng lượng cân bằng hàng ngày cho mèo trưởng thành. Hàm lượng canxi và phospho tối ưu giúp xương và răng chắc khỏe. Bổ sung Omega 3 & 6 và kẽm giúp nuôi dưỡng làn da khỏe mạnh và duy trì bộ lông bóng mượt tự nhiên.', usage_instructions = 'Cho ăn trực tiếp, chia làm 2 bữa/ngày theo hướng dẫn trên bao bì. Luôn luôn để sẵn bát nước sạch bên cạnh. Tránh thay đổi thức ăn đột ngột, nên trộn dần hạt mới với hạt cũ trong vòng 7 ngày để hệ tiêu hóa của mèo thích nghi dần.', specs = '', badge = null, stock = 0, rating = 4.5, review_count = 87 WHERE id = 'a0000000-0000-0000-0000-000000000004';
UPDATE public.product SET origin = 'Canada', ingredients = 'Thịt gà tươi (20%), thịt gà tây tươi (15%), gan gà tươi (10%), cá trích nguyên con tươi (5%), cá bơn nguyên con tươi, trứng tươi, chất xơ táo, bí ngô, cà rốt, tảo bẹ.', benefits = 'Cung cấp hàm lượng protein siêu cao (44%) từ nguồn thịt động vật đa dạng giúp phát triển cơ bắp săn chắc và duy trì cân nặng lý tưởng, hạn chế béo phì ở mèo nuôi trong nhà. Công thức Grain-free không chứa ngũ cốc bảo vệ hệ tiêu hóa nhạy cảm.', usage_instructions = 'Cho ăn trực tiếp. Chia khẩu phần dựa trên hướng dẫn cân nặng trên bao bì. Luôn chuẩn bị sẵn nước uống sạch tinh khiết bên cạnh để mèo uống tự do.', specs = 'Túi 1.8kg hạt sấy khô nguyên chất, giàu đạm động vật tự nhiên, thích hợp cho mèo mọi lứa tuổi', badge = null, stock = 22, rating = 4.9, review_count = 94 WHERE id = 'a0000000-0000-0000-0000-000000000005';
UPDATE public.product SET origin = 'Mỹ', ingredients = 'Thịt bò Bison nướng (15%), thịt nai nướng (15%), bột thịt gà, khoai lang, đậu bản, khoai tây, dầu hạt cải, bột cá biển, men bia, cà chua, quả việt quất, quả mâm xôi.', benefits = 'Mang đến hương vị thịt nướng hoang dã thơm ngon kích thích vị giác của cún cưng. Cung cấp nguồn năng lượng dồi dào dễ tiêu hóa từ khoai lang và các loại đậu. Bổ sung hệ lợi khuẩn độc quyền giúp tăng cường hệ miễn dịch và tiêu hóa khỏe mạnh.', usage_instructions = 'Cho ăn trực tiếp, căn cứ vào mức độ hoạt động và cân nặng của chó để phân chia lượng thức ăn phù hợp theo bảng chỉ dẫn bao bì. Luôn để sẵn nguồn nước uống sạch.', specs = 'Túi 2.0kg, dạng hạt giòn tan vị thịt bison và nai nướng hoang dã, thích hợp cho chó trưởng thành', badge = null, stock = 15, rating = 4.8, review_count = 76 WHERE id = 'a0000000-0000-0000-0000-000000000006';
UPDATE public.product SET origin = 'Việt Nam', ingredients = 'Thịt thăn bò tươi (55%), bí đỏ (15%), cà rốt (10%), khoai tây (10%), nước hầm xương bò cô đặc (8%), vitamin tổng hợp và dầu dừa nguyên chất (2%).', benefits = 'Pate tươi được nấu chín chậm giữ nguyên dưỡng chất, cung cấp nguồn sắt, kẽm và protein chất lượng cao giúp cún miu tăng cân khỏe mạnh và bổ mắt nhờ tiền vitamin A từ bí đỏ và cà rốt.', usage_instructions = 'Trộn trực tiếp vào hạt hoặc cho ăn riêng như bữa chính. Đối với bé có hệ tiêu hóa nhạy cảm, nên hâm nóng ấm nhẹ bằng lò vi sóng trong 10-15 giây trước khi cho ăn. Bảo quản lạnh từ 0-4 độ C ngay sau khi nhận hàng.', specs = 'Hộp nhựa PP 300g đóng kín bằng màng seal y tế, pate tươi dạng sệt xay nhỏ vừa phải dễ nhai', badge = 'best', stock = 50, rating = 4.9, review_count = 115 WHERE id = 'a0000000-0000-0000-0000-000000000007';
UPDATE public.product SET origin = 'Pháp', ingredients = 'Thịt động vật và dẫn xuất từ thịt, cá và dẫn xuất từ cá (nguồn Omega 3 & 6), ngũ cốc, chiết xuất protein thực vật, khoáng chất thiết yếu, các loại đường khác nhau.', benefits = 'Nuôi dưỡng và phục hồi làn da nhạy cảm của mèo, nuôi dưỡng nang lông giúp lông mọc dày và có độ bóng mượt vượt trội. Hỗ trợ hệ tiết niệu khỏe mạnh nhờ độ ẩm cao và duy trì cân nặng lý tưởng.', usage_instructions = 'Cho mèo ăn 1-2 lon/ngày chia làm các bữa. Có thể dùng làm thức ăn chính hoặc trộn lẫn với hạt khô Royal Canin để kích thích mèo ăn ngon miệng hơn.', specs = 'Hộp thiếc 85g dạng lát mỏng ngập trong nước sốt thịt đậm đà, dành cho mèo trưởng thành dưỡng lông', badge = 'hot', stock = 80, rating = 4.8, review_count = 142 WHERE id = 'a0000000-0000-0000-0000-000000000008';
UPDATE public.product SET origin = 'Trung Quốc', ingredients = 'Thịt ức gà tươi (85%), tinh bột sắn, chiết xuất men bia, dầu cá hồi dưỡng lông, vitamin A, B2, B3, B5, D3, E, taurine cần thiết cho mắt mèo.', benefits = 'Bổ sung nước hiệu quả cho mèo lười uống nước. Cung cấp protein dễ hấp thụ giúp mèo nhanh nhẹn, tinh anh. Bổ sung vitamin E chống oxy hóa tăng sức đề kháng tự nhiên.', usage_instructions = 'Cho ăn trực tiếp bằng cách bóp súp cho mèo liếm dần từ gói, hoặc trộn vào thức ăn chính để tăng hương vị ngọt thanh thơm ngon của ức gà.', specs = 'Gói gồm 5 thanh x 15g dạng súp sệt mịn thơm, thích hợp làm bữa phụ tương tác vui đùa', badge = null, stock = 90, rating = 4.6, review_count = 168 WHERE id = 'a0000000-0000-0000-0000-000000000009';
UPDATE public.product SET origin = 'Na Uy', ingredients = '100% dầu cá hồi tự nhiên khai thác tại vùng biển sâu Na Uy, được ép lạnh tinh khiết để giữ nguyên vẹn hàm lượng acid béo thiết yếu EPA (8%) và DHA (10%).', benefits = 'Giảm viêm da dị ứng, giảm ngứa ngáy nổi mẩn, kích thích mọc lông dày mềm mượt, ngăn ngừa rụng lông rõ rệt sau 2-4 tuần sử dụng. Bổ sung dưỡng chất phát triển não bộ và thị lực.', usage_instructions = 'Trộn trực tiếp vào thức ăn hạt hoặc pate của chó mèo. Liều lượng sử dụng: Nhấn 1-2 lần vòi xịt (cho pet < 5kg), 3-4 lần (cho pet 5-15kg) hàng ngày.', specs = 'Chai nhôm cao cấp 150ml vòi xịt tiện lợi chống oxy hóa dầu cá, bảo quản mát tránh ánh nắng', badge = 'new', stock = 35, rating = 4.9, review_count = 98 WHERE id = 'a0000000-0000-0000-0000-000000000010';
UPDATE public.product SET origin = 'Pháp', ingredients = 'Hàm lượng cao Vitamin A, D3, E, B1, B2, B6, B12, Canxi pantothenate, Niacinamide, Sắt, Mangan, Magiê, Kali, chất béo dễ hấp thu chiết xuất từ mỡ động vật.', benefits = 'Cung cấp năng lượng đậm đặc và các vitamin khoáng chất thiết yếu tức thì cho chó mèo bị suy nhược, bỏ ăn lâu ngày, chó mèo mẹ sau sinh, thú cưng đang dưỡng bệnh sau phẫu thuật.', usage_instructions = 'Cho thú cưng ăn trực tiếp từ ngón tay hoặc bôi lên miệng/bàn chân để thú cưng tự liếm. Liều lượng: 1-2 muỗng cà phê (khoảng 5-10cm gel) cho 5kg thể trọng cơ thể mỗi ngày.', specs = 'Tuýp nhôm bọc nhựa 120.5g dạng gel đặc màu nâu, vị mạch nha thơm bùi kích thích vị giác thèm ăn', badge = 'hot', stock = 28, rating = 4.9, review_count = 156 WHERE id = 'a0000000-0000-0000-0000-000000000011';
UPDATE public.product SET origin = 'Mỹ', ingredients = 'Hệ lợi khuẩn sống đậm đặc (Lactobacillus acidophilus, Bifidobacterium bifidum, Enterococcus faecium...) đạt tối thiểu 20 triệu CFU/gram gel, prebiotic FOS.', benefits = 'Thiết lập và cân bằng lại hệ vi sinh đường ruột tức thì, trị tiêu chảy, phân lỏng do thay đổi thức ăn đột ngột, stress khi đổi môi trường, hoặc sau khi dùng kháng sinh lâu ngày.', usage_instructions = 'Bơm trực tiếp vào miệng thú cưng theo vạch chia trên ống xi-lanh. Liều lượng: 1g cho mỗi 4.5kg thể trọng cơ thể. Sử dụng định kỳ 2 lần/tuần để duy trì tiêu hóa tốt.', specs = 'Xi-lanh nhựa chia vạch 15g dạng gel đặc vị ngọt dễ cho uống trực tiếp, tiện lợi sử dụng', badge = 'new', stock = 14, rating = 4.9, review_count = 42 WHERE id = 'a0000000-0000-0000-0000-000000000012';
UPDATE public.product SET origin = 'Trung Quốc', ingredients = 'Các loại hạt ngũ cốc tự nhiên (lúa mạch, yến mạch, ngô bắp), hạt hướng dương giàu béo, cỏ nén linh lăng, rau củ quả sấy khô (cà rốt, chuối, đu đủ), tôm khô mini.', benefits = 'Cung cấp dinh dưỡng hoàn chỉnh cân bằng giúp Hamster khỏe mạnh, lanh lợi. Thiết kế hạt thô cứng vừa phải giúp Hamster mài răng tự nhiên trong lúc nhai, ngăn ngừa các bệnh răng mọc quá dài đâm vào nướu.', usage_instructions = 'Cho ăn hàng ngày. Đổ đầy khay ăn nhỏ của Hamster. Đảm bảo thay thức ăn thừa mỗi ngày để tránh ẩm mốc. Luôn để sẵn bình nước sạch.', specs = 'Gói 1kg hỗn hợp hạt ngũ cốc đa dạng, dành riêng cho các dòng Hamster (Winter White, Robo, Bear)', badge = 'best', stock = 60, rating = 4.7, review_count = 104 WHERE id = 'a0000000-0000-0000-0000-000000000013';
UPDATE public.product SET origin = 'Mỹ', ingredients = '100% cỏ Timothy hữu cơ nguyên chất thu hoạch ở giai đoạn đầu, sấy khô giữ nguyên màu xanh tươi, mùi hương cỏ đồng nội thơm nhẹ tự nhiên.', benefits = 'Nguồn chất xơ dồi dào hỗ trợ hệ tiêu hóa nhạy cảm của thỏ hoạt động trơn tru, ngăn ngừa đầy hơi táo bón. Giúp mài mòn răng thỏ tự nhiên, bảo vệ sức khỏe răng miệng tối đa.', usage_instructions = 'Cho thỏ ăn tự do không giới hạn lượng cỏ khô mỗi ngày. Cỏ Timothy nên chiếm 80% khẩu phần ăn hàng ngày của thỏ. Loại bỏ những phần cỏ cũ bị ướt/bẩn trong chuồng.', specs = 'Gói đóng ép bánh 1kg cỏ khô nguyên cọng, không bụi, thơm mát tự nhiên cho thỏ và bọ ú', badge = 'hot', stock = 40, rating = 4.8, review_count = 83 WHERE id = 'a0000000-0000-0000-0000-000000000014';
UPDATE public.product SET origin = 'Trung Quốc', ingredients = 'Bột cỏ Timothy, bột yến mạch hữu cơ, hương dâu tây tự nhiên, vitamin tổng hợp, canxi, chất xơ thô thực vật nén ép áp lực cực cao.', benefits = 'Cung cấp bánh ăn dặm mài răng cứng chắc giúp thú nhỏ giải trí và bào mòn răng cửa liên tục mọc dài. Bổ sung xơ thô và khoáng chất canxi giúp xương chắc khỏe.', usage_instructions = 'Cho ăn trực tiếp như bánh thưởng. Khẩu phần khuyến nghị: 1-2 cái/tuần tùy thuộc vào kích thước của Hamster hoặc thỏ. Đặt trực tiếp vào chuồng.', specs = 'Túi zip 150g chứa 10 bánh nén hình khúc tròn vị dâu thơm ngọt kích thích vị giác thú nhỏ', badge = 'new', stock = 120, rating = 4.5, review_count = 62 WHERE id = 'a0000000-0000-0000-0000-000000000015';
UPDATE public.product SET origin = 'Trung Quốc', ingredients = 'Nhựa PP cao cấp nguyên sinh không chứa BPA gây hại, lòng bát bằng inox 304 không gỉ độ bền cao, đệm cao su chống trượt dưới đáy bát.', benefits = 'Thiết kế cấu trúc rãnh chứa nước xung quanh chống kiến, gián và các loại côn trùng bò vào thức ăn của thú cưng một cách triệt để. Hai lòng bát inox giúp đựng song song nước uống và thức ăn tiện lợi, chất liệu inox kháng khuẩn tốt và ngăn ngừa hiện tượng đen cằm ở mèo.', usage_instructions = 'Đổ một lượng nước nhỏ vào rãnh xung quanh để ngăn côn trùng bò qua. Bỏ thức ăn vào lòng bát inox bên trái và nước sạch vào bát bên phải. Vệ sinh lòng bát inox hàng ngày bằng nước rửa bát dịu nhẹ và phơi khô ráo.', specs = '', badge = 'new', stock = 25, rating = 4.6, review_count = 62 WHERE id = 'a0000000-0000-0000-0000-000000000016';
UPDATE public.product SET origin = 'Mỹ', ingredients = 'Thân bình làm từ nhựa ABS dày dặn chịu lực tốt, đầu vòi bằng thép không gỉ 304 chống rỉ sét, lò xo thép kép, bi lăn tròn làm từ thép cao cấp.', benefits = 'Cung cấp giải pháp uống nước sạch tuyệt đối cho thú cưng trong chuồng, loại bỏ tình trạng nước bị bụi bẩn, lông rụng hay thức ăn rơi vào. Thiết kế đầu bi lăn tự động chỉ chảy nước khi thú cưng liếm giúp giữ cho lông cằm và sàn chuồng luôn khô ráo, sạch sẽ.', usage_instructions = 'Đổ đầy nước vào bình (bắt buộc phải đổ đầy để tạo áp suất chân không chống rò nước), vặn chặt vòi phun. Gài bình nước vào nan chuồng sắt ở chiều cao phù hợp với tầm với của thú cưng, dùng tay ấn nhẹ thử đầu bi để nước chảy ra kiểm tra trước.', specs = '', badge = 'hot', stock = 12, rating = 4.7, review_count = 43 WHERE id = 'a0000000-0000-0000-0000-000000000017';
UPDATE public.product SET origin = 'Trung Quốc', ingredients = 'Vỏ máy nhựa Tritan cao cấp tiêu chuẩn thực phẩm, lõi lọc 3 lớp (vải không dệt, than hoạt tính gáo dừa, nhựa trao đổi ion), bơm nước không dây siêu êm.', benefits = 'Tạo ra dòng nước tuần hoàn giàu oxy mô phỏng dòng suối tự nhiên nhằm kích thích bản năng uống nước nhiều hơn của thú cưng, ngăn ngừa bệnh suy thận nguy hiểm. Hệ thống lọc 3 lớp lọc sạch bụi bẩn, lông rụng, kim loại nặng và mùi clo trong nước máy.', usage_instructions = 'Lắp ráp máy theo sách hướng dẫn. Ngâm lõi lọc mới trong nước 10 phút trước khi lắp. Đổ nước sạch vào khay chứa tối đa 1.35L, cắm dây USB vào củ sạc. Nhấn nút chuyển đổi chế độ Smart (bơm ngắt quãng) hoặc Normal (bơm liên tục). Thay lõi lọc mỗi 30 ngày.', specs = '', badge = null, stock = 0, rating = 4.9, review_count = 54 WHERE id = 'a0000000-0000-0000-0000-000000000018';
UPDATE public.product SET origin = 'Việt Nam', ingredients = 'Chén làm bằng đất sét trắng nung ở nhiệt độ cao tráng men sứ vân đá hoa cương cao cấp, chân đế làm bằng gỗ tre tự nhiên được phủ lớp sơn chống ẩm mốc.', benefits = 'Nâng chiều cao bát ăn lên 10cm với độ nghiêng 15 độ khoa học giúp bảo vệ cột sống cổ của thú cưng, làm giảm đáng kể áp lực lên khớp xương khi ăn. Giúp hạn chế tình trạng trào ngược dạ dày, nôn trớ thức ăn và hỗ trợ tiêu hóa tốt hơn.', usage_instructions = 'Đặt đế gỗ cố định trên sàn nhà phẳng, đặt chén sứ lên khay nghiêng của đế gỗ. Đổ thức ăn hạt hoặc pate vào chén cho pet ăn. Chén sứ chịu nhiệt tốt nên có thể sử dụng an toàn trong lò vi sóng để hâm nóng pate và rửa sạch trong máy rửa bát.', specs = '', badge = 'new', stock = 18, rating = 4.8, review_count = 39 WHERE id = 'a0000000-0000-0000-0000-000000000019';
UPDATE public.product SET origin = 'Trung Quốc', ingredients = 'Nhựa ABS cao cấp nguyên sinh chống bám bẩn, bát ăn bằng thép không gỉ 304 tháo rời, hệ thống khóa silicon kín chống kiến gián xâm nhập và giữ hạt luôn giòn.', benefits = 'Tự động cung cấp hạt thức ăn cho chó mèo đúng giờ và định lượng khoa học theo thiết lập trên điện thoại qua kết nối App Bluetooth. Tránh tình trạng pet ăn quá nhiều gây béo phì hoặc bị đói khi chủ vắng nhà đột xuất.', usage_instructions = 'Tải App Petkit kết nối máy qua Bluetooth. Đổ hạt khô vào khay chứa tối đa 3L hạt. Thiết lập lịch ăn tự động chi tiết (giờ ăn, số gram). Định kỳ tháo bát inox ra rửa sạch để tránh phát sinh vi khuẩn gây mụn cằm ở mèo.', specs = 'Dung tích 3L hạt khô, thiết kế chống kẹt hạt thông minh, hoạt động bằng pin dự phòng khi mất điện', badge = 'best', stock = 8, rating = 4.9, review_count = 35 WHERE id = 'a0000000-0000-0000-0000-000000000020';
UPDATE public.product SET origin = 'Trung Quốc', ingredients = 'Carton gợn sóng nén mật độ cao thân thiện môi trường độ bền vượt trội gấp 3 lần carton thường, keo dán sinh học hữu cơ lành tính không chứa hóa chất độc hại amoniac.', benefits = 'Đáp ứng bản năng cào móng tự nhiên của mèo, giúp loại bỏ lớp móng chết cũ. Bảo vệ thảm trải sàn, chân ghế sofa, rèm cửa trong nhà không bị mèo cào rách xước. Dùng làm chỗ nằm ngủ thư giãn thoải mái cho mèo.', usage_instructions = 'Đặt bàn cào móng ở vị trí gần nơi mèo hay ngủ hoặc góc phòng mèo thích chơi. Rắc một lượng nhỏ cỏ mèo Catnip đi kèm lên bề mặt bàn cào để kích thích, tạo sự chú ý thu hút mèo đến cào móng tự nhiên.', specs = 'Kích thước 45x25x6cm hình gợn sóng uốn lượn thoải mái, kèm túi bột cỏ mèo Catnip sấy khô thơm nhẹ', badge = null, stock = 30, rating = 4.7, review_count = 84 WHERE id = 'a0000000-0000-0000-0000-000000000021';
UPDATE public.product SET origin = 'Trung Quốc', ingredients = 'Mica nhập khẩu trong suốt chịu lực tốt chống trầy xước, các nan sắt sơn tĩnh điện thoáng khí, các chi tiết cầu trượt và tầng lửng bằng nhựa màu pastel.', benefits = 'Cung cấp không gian sống lâu đài lộng lẫy, rộng rãi cho Hamster leo trèo vui đùa. Chất liệu Mica trong suốt 100% giúp chủ nuôi dễ dàng quan sát mọi cử động hoạt động đáng yêu của bé từ bên ngoài.', usage_instructions = 'Lắp ráp các tấm mica và khay nhựa theo giấy hướng dẫn. Đặt các đồ chơi phụ kiện (bánh chạy, khay ăn, bình nước) vào các vị trí thích hợp. Trải cát/mùn cưa dày 2-3cm ở khay đáy chuồng. Vệ sinh chuồng 1 lần/tuần.', specs = 'Kích thước 47x32x35cm lồng 3 tầng sang trọng đầy đủ phụ kiện đi kèm (bánh chạy, võng nằm, khay ăn)', badge = 'new', stock = 15, rating = 4.8, review_count = 34 WHERE id = 'a0000000-0000-0000-0000-000000000022';
UPDATE public.product SET origin = 'Việt Nam', ingredients = 'Sứ trắng tráng men cao cấp nung ở nhiệt độ 1300 độ C loại bỏ tạp chất chì độc hại, vẽ tay hoa văn hình củ cà rốt cam nổi bật đáng yêu.', benefits = 'Thiết kế nặng tay chống lật bát, tránh tình trạng Hamster hoặc thỏ nghịch ngợm giẫm chân làm đổ thức ăn hạt ra chuồng gây lãng phí bẩn chuồng. Sứ tráng men dễ chùi rửa.', usage_instructions = 'Đặt bát ăn cố định ở một góc bằng phẳng trong chuồng. Đổ thức ăn hạt ngũ cốc vào khay ăn. Rửa sạch bằng nước ấm sau mỗi bữa ăn của thú nhỏ.', specs = 'Đường kính bát 10cm, sâu 4cm nặng 200g hình cà rốt dễ thương thích hợp cho thỏ, hamster, bọ ú', badge = 'best', stock = 45, rating = 4.9, review_count = 52 WHERE id = 'a0000000-0000-0000-0000-000000000023';
UPDATE public.product SET origin = 'Trung Quốc', ingredients = 'Tay cầm bằng nhựa ABS bọc cao su chống trượt, hệ thống kim chải inox không gỉ có bọc hạt nhựa mềm ở đầu kim, nút nhấn đẩy cơ học bằng lò xo.', benefits = 'Loại bỏ tới 95% lông rụng, lông chết trên cơ thể chó mèo mà không làm tổn thương da khỏe mạnh. Hỗ trợ gỡ các búi lông rối nhẹ nhàng, đồng thời các đầu bọc nhựa giúp massage tăng tuần hoàn máu dưới da, kích thích mọc lông mới mềm mượt hơn.', usage_instructions = 'Chải nhẹ nhàng dọc theo hướng lông mọc từ đầu đến đuôi. Tránh dùng lực quá mạnh ở các vùng nhạy cảm như bụng, tai. Sau khi chải xong và lông bám đầy trên mặt lược, nhấn nút tròn lớn sau lưng lược để đẩy toàn bộ búi lông rụng ra ngoài chỉ với 1 chạm.', specs = 'Màu xanh mint mát mắt, kích thước mặt lược rộng 10cm với 250 kim chải bọc đầu nhựa chống xước da', badge = 'best', stock = 35, rating = 4.7, review_count = 112 WHERE id = 'a0000000-0000-0000-0000-000000000024';
UPDATE public.product SET origin = 'Trung Quốc', ingredients = 'Lưỡi kìm bằng thép không gỉ tôi cứng sắc bén, thân kìm bằng nhựa ABS cao cấp, tích hợp bóng đèn LED siêu sáng dùng pin cúc áo, lò xo trợ lực có độ đàn hồi cao.', benefits = 'Giúp chủ nuôi cắt tỉa móng chân thú cưng định kỳ một cách gọn gàng, an toàn tại nhà. Đèn LED siêu sáng chiếu trực tiếp soi rõ tủy máu bên trong móng, hạn chế tối đa nguy cơ cắt phạm gây đau đớn và chảy máu cho bé. Thiết kế khay hứng chống móng bắn tung tóe.', usage_instructions = 'Bật công tắc đèn LED trên tay cầm. Giữ bàn chân thú cưng chắc chắn, ấn nhẹ để móng lộ ra. Đặt kìm một góc 45 độ so với móng, quan sát kỹ dải màu hồng (tủy máu) rồi dứt khoát bấm cắt ở vùng móng trắng bên ngoài. Dùng giũa móng tích hợp ở đuôi kìm để mài mịn.', specs = 'Tích hợp đèn LED soi tủy móng, có khay nhựa hứng móng cắt, kèm giũa móng ở cán cầm tiện lợi', badge = 'hot', stock = 2, rating = 4.9, review_count = 83 WHERE id = 'a0000000-0000-0000-0000-000000000025';
UPDATE public.product SET origin = 'Trung Quốc', ingredients = '100% bã đậu nành tự nhiên nguyên chất, tinh bột bắp hữu cơ, chiết xuất trà xanh kháng khuẩn khử mùi, chất kết dính thực vật hoàn toàn lành tính.', benefits = 'Thấm hút chất thải cực nhanh và vón cục chặt chỉ trong 3 giây sau khi tiếp xúc với chất lỏng. Khử mùi hôi amoniac vượt trội nhờ tinh chất trà xanh tự nhiên. Không bụi 99.9%, bảo vệ hệ hô hấp cho thú cưng và chủ nuôi. Đặc biệt có thể xả trực tiếp vào bồn cầu.', usage_instructions = 'Đổ cát vào khay vệ sinh sạch sẽ với độ dày từ 5-7cm để đạt hiệu quả thấm hút tốt nhất. Sử dụng xẻng xúc bỏ các cục cát vón và chất thải rắn hàng ngày. Đổ thêm cát mới để duy trì độ dày tiêu chuẩn. Có thể tiêu hủy bằng cách xả từng lượng nhỏ trong bồn cầu.', specs = 'Túi hút chân không 6L (~2.5kg), đường kính hạt cát siêu nhỏ 2mm hạn chế bám kẽ chân mèo', badge = 'best', stock = 150, rating = 4.8, review_count = 345 WHERE id = 'a0000000-0000-0000-0000-000000000026';
UPDATE public.product SET origin = 'Trung Quốc', ingredients = 'Vỏ máy làm từ nhựa ABS chịu lực tốt, động cơ hút chân không chổi than công suất cao, bộ lọc HEPA lọc bụi mịn, pin sạc Lithium dung lượng lớn.', benefits = 'Hút sạch lông rụng, bụi mịn và gàu da của thú cưng bám dính trên các bề mặt vải như ghế sofa, nệm giường, quần áo, thảm trải sàn. Giúp làm sạch không gian sống nhanh chóng, ngăn ngừa các tác nhân gây dị ứng đường hô hấp cho gia đình.', usage_instructions = 'Sạc đầy pin cho máy bằng cáp sạc USB đi kèm. Bật nút nguồn, chọn chế độ hút phù hợp (Eco hoặc Max). Rà nhẹ nhàng đầu hút chứa chổi quét lên bề mặt vải cần làm sạch. Sau khi hút xong, nhấn nút mở hộp bụi để đổ lông rụng và vệ sinh màng lọc HEPA.', specs = 'Thiết kế cầm tay không dây siêu nhẹ 0.8kg, cổng sạc Type-C tiện lợi, lực hút 8000Pa mạnh mẽ', badge = 'new', stock = 0, rating = 4.6, review_count = 28 WHERE id = 'a0000000-0000-0000-0000-000000000027';
UPDATE public.product SET origin = 'Trung Quốc', ingredients = 'Nhựa ABS chịu lực cao, hệ thống cảm biến hồng ngoại thông minh x6, cảm biến trọng lượng x4, màng lọc phân chuyên dụng, bình xịt khử mùi tự động xịt tinh dầu.', benefits = 'Tự động dọn sạch phân và chất thải vón cục của mèo sau mỗi lần đi vệ sinh, gom vào khay rác kín giúp gia đình hoàn toàn thoát khỏi việc xúc phân thủ công hàng ngày và loại bỏ mùi hôi thối trong nhà.', usage_instructions = 'Đặt máy ở mặt phẳng cứng vững. Tải ứng dụng Petkit, liên kết máy qua Wifi. Đổ cát đậu nành hạt nhỏ (<2.5mm) hoặc cát đất sét vào lòng máy. Thay túi đựng rác ở khay chứa sau mỗi 5-7 ngày tùy số lượng mèo.', specs = 'Dung tích cabin lớn 76L thích hợp mèo từ 1.5 - 10kg, bình xịt khử mùi Pura Air thông minh tích hợp', badge = null, stock = 5, rating = 4.9, review_count = 46 WHERE id = 'a0000000-0000-0000-0000-000000000028';
UPDATE public.product SET origin = 'Việt Nam', ingredients = 'Nước điện hóa ion bạc (Ag+), cồn sinh học từ mía đường, enzym phân hủy sinh học, tinh dầu hoa oải hương (Lavender) tự nhiên nguyên chất.', benefits = 'Tiêu diệt 99.9% vi khuẩn, nấm mốc gây mùi hôi khó chịu trên cơ thể thú cưng, khay vệ sinh, nệm ngủ, chuồng quây. Phân hủy tận gốc phân tử mùi amoniac thay vì chỉ che phủ mùi tạm thời.', usage_instructions = 'Xịt trực tiếp lên khay vệ sinh của mèo sau khi dọn, xịt vào nệm, lồng chuồng từ khoảng cách 20-30cm. Có thể xịt trực tiếp lên lông thú cưng (tránh vùng mắt) để khử mùi cấp tốc rồi dùng khăn lau khô.', specs = 'Chai nhựa vòi xịt phun sương mịn 350ml, hương hoa Lavender dịu nhẹ thơm mát thư giãn tinh thần', badge = 'new', stock = 55, rating = 4.8, review_count = 112 WHERE id = 'a0000000-0000-0000-0000-000000000029';
UPDATE public.product SET origin = 'Trung Quốc', ingredients = 'Bông xơ tự nhiên, hạt siêu thấm hút SAP nhập khẩu Nhật Bản, màng đáy PE thoáng khí chống tràn nước, băng keo dán velcro thông minh tái sử dụng nhiều lần.', benefits = 'Giải pháp vệ sinh hoàn hảo cho cún cưng khi đi du lịch, đi tàu xe, cún cái trong kỳ kinh nguyệt (salơ), cún đực có thói quen đánh dấu lãnh thổ trong nhà, hoặc cún già mất kiểm soát tiểu tiện.', usage_instructions = 'Mở tã, xỏ đuôi cún qua lỗ tròn khoét sẵn ở đuôi tã. Quấn tã ôm sát hông cún đùi sau, kéo hai miếng keo dán cố định chặt ở hai bên hông sao cho tã vừa khít không bị lỏng lẻo khi cún chạy nhảy.', specs = 'Bịch 20 cái, size S (cho chó từ 2-5kg, vòng bụng 25-40cm), thấm hút khóa chất lỏng lên đến 800ml', badge = null, stock = 40, rating = 4.7, review_count = 73 WHERE id = 'a0000000-0000-0000-0000-000000000030';
UPDATE public.product SET origin = 'Trung Quốc', ingredients = '100% cát thạch anh khai thác tự nhiên được xử lý nhiệt ở nhiệt độ cao, tinh dầu chiết xuất từ táo tây thơm dịu kháng khuẩn da.', benefits = 'Giúp Hamster tắm khô loại bỏ bã nhờn, dầu thừa trên da lông, ngăn ngừa các bệnh ghẻ nấm do độ ẩm cao. Tạo mùi hương táo tươi mát lưu hương dễ chịu trên cơ thể bé.', usage_instructions = 'Đổ cát tắm vào phòng tắm chuyên dụng của Hamster cao khoảng 1-2cm. Hamster sẽ tự lăn lộn tắm khô tự nhiên. Thay cát tắm mới sau 2-3 ngày hoặc khi phát hiện cát bị bám bẩn nước tiểu.', specs = 'Túi zip 1kg hạt cát siêu nhỏ bo tròn không sắc nhọn, không tạo bụi bẩn, hương thơm mát dịu', badge = 'best', stock = 100, rating = 4.7, review_count = 94 WHERE id = 'a0000000-0000-0000-0000-000000000031';
UPDATE public.product SET origin = 'Trung Quốc', ingredients = 'Nhựa PC trong suốt chịu lực cao chống va đập, vải Oxford cao cấp chống thấm nước, các lỗ thông khí bằng kim loại và lưới hai bên hông.', benefits = 'Cung cấp không gian vận chuyển thú cưng an toàn và thoáng mát khi đi ra ngoài, đi thú y hoặc đi dạo. Mặt kính nhựa trong suốt tạo tầm nhìn rộng rãi giúp thú cưng dễ dàng quan sát thế giới bên ngoài, từ đó giảm cảm giác sợ hãi, lo lắng khi di chuyển.', usage_instructions = 'Mở khóa balo kéo hết cỡ, đặt tã lót mỏng xuống đáy nếu sợ bé tè. Cho thú cưng vào trong nhẹ nhàng, cài móc khóa an toàn trong balo vào vòng cổ của bé để tránh bé nhảy vọt ra ngoài khi mở balo. Kéo khóa lại chắc chắn và đeo lên vai.', specs = 'Kích thước 42x33x25cm, tải trọng tối đa cho pet < 7kg (mèo) hoặc < 5kg (chó), màu vàng tươi', badge = null, stock = 40, rating = 4.5, review_count = 99 WHERE id = 'a0000000-0000-0000-0000-000000000032';
UPDATE public.product SET origin = 'Trung Quốc', ingredients = 'Mặt trên bằng vải bông lông cừu nhân tạo siêu mềm mại, lõi nhồi bông PP xoắn 3D đàn hồi cao chống xẹp lún, mặt đáy bằng vải Oxford chống trượt và chống thấm ẩm.', benefits = 'Tạo không gian ngủ ấm áp, êm ái, nâng niu giấc ngủ cho chó mèo. Độ nâng đỡ tối ưu từ bông PP giúp bảo vệ hệ xương khớp non nớt hoặc thoái hóa của thú cưng, giúp giảm thiểu căng thẳng và mang lại cảm giác an toàn như được mẹ ôm ấp.', usage_instructions = 'Đặt nệm ở góc nhà khô ráo, thoáng mát, tránh ánh nắng trực tiếp hoặc nơi ẩm ướt. Định kỳ hàng tuần đem nệm ra phơi nắng để khử trùng. Khi giặt, có thể giặt máy ở chế độ nhẹ nhàng với túi giặt và nước giặt trung tính, không sấy nhiệt độ cao.', specs = 'Kích thước 50x50x12cm, màu xám ghi sang trọng, phù hợp cho chó mèo có cân nặng dưới 7kg', badge = 'hot', stock = 15, rating = 4.9, review_count = 47 WHERE id = 'a0000000-0000-0000-0000-000000000033';
UPDATE public.product SET origin = 'Trung Quốc', ingredients = 'Các tấm lưới bằng sắt phi dày dặn được phủ lớp sơn tĩnh điện chống rỉ sét bong tróc, các chốt nối bằng nhựa ABS cứng lực chống nứt vỡ.', benefits = 'Quây vùng không gian an toàn cho thú cưng chơi đùa, nghỉ ngơi khi chủ nuôi đi vắng, ngăn thú cưng cắn phá đồ đạc trong nhà. Thiết kế lắp ghép thông minh cho phép tự do thay đổi kích thước, kiểu dáng chuồng theo diện tích phòng thực tế.', usage_instructions = 'Lên ý tưởng hình dáng chuồng (quây vuông, quây chữ L, quây 2 tầng). Lắp các tấm sắt vào rãnh chốt nhựa ABS, dùng búa gỗ nhỏ đi kèm gõ nhẹ dứt khoát vào các khớp nối để cố định chắc chắn. Có thể mua thêm các tấm ghép để mở rộng diện tích.', specs = 'Bộ gồm 12 tấm lưới sắt kích thước 35x35cm và 24 chốt nhựa kết nối, có cửa mở tiện lợi, màu đen', badge = null, stock = 8, rating = 4.7, review_count = 36 WHERE id = 'a0000000-0000-0000-0000-000000000034';
UPDATE public.product SET origin = 'Mỹ', ingredients = 'Nhựa PP cao cấp nguyên sinh chống trầy xước không chứa BPA, 3 quả bóng nhựa có chuông lục lạc phát ra âm thanh nhỏ bên trong, đệm cao su đáy.', benefits = 'Giúp mèo giải trí tự lập, giảm căng thẳng stress hiệu quả khi chủ vắng nhà. Kích thích bản năng săn mồi, vồ bắt tự nhiên của mèo thông qua chuyển động tròn của bóng, tăng cường vận động thể chất giúp giảm nguy cơ béo phì ở mèo nuôi trong nhà.', usage_instructions = 'Đặt tháp bóng trên nền nhà phẳng. Dùng tay gạt nhẹ các quả bóng chạy vòng quanh các tầng để tạo sự chú ý cho mèo. Mèo sẽ tự dùng chân gạt bóng qua các khe hở. Thích hợp cho hộ gia đình nuôi nhiều mèo chơi cùng nhau.', specs = 'Tháp nhựa 3 tầng màu cam nổi bật, đường kính đáy 25cm, có 3 quả bóng màu sắc chuyển động mượt mà', badge = 'best', stock = 50, rating = 4.8, review_count = 184 WHERE id = 'a0000000-0000-0000-0000-000000000035';
UPDATE public.product SET origin = 'Trung Quốc', ingredients = 'Vải nỉ bông tự nhiên co giãn tốt, lớp lót bông mịn ấm áp, phần bo cổ và tay áo làm từ thun bo gân co giãn mềm mại không gây bó siết da thú cưng.', benefits = 'Giúp giữ ấm cơ thể hiệu quả cho chó mèo vào mùa đông lạnh hoặc khi nằm phòng điều hòa lạnh, hạn chế các bệnh cảm lạnh, viêm phổi. Làm đẹp thời trang độc đáo cho thú cưng khi đi dạo phố, chụp hình check-in cùng chủ nuôi.', usage_instructions = 'Chọn size áo phù hợp dựa trên số đo vòng ngực và cân nặng của bé. Nhẹ nhàng xỏ hai chân trước của thú cưng vào ống tay áo, sau đó kéo cổ áo qua đầu và vuốt thẳng thân áo dọc theo lưng. Nên giặt bằng tay để tránh làm xù lông nỉ.', specs = 'Size M (vòng ngực 38-42cm, chiều dài lưng 28-32cm, cho pet 3-5kg), họa tiết kẻ sọc đỏ trắng thời thượng', badge = 'new', stock = 4, rating = 4.6, review_count = 19 WHERE id = 'a0000000-0000-0000-0000-000000000036';
UPDATE public.product SET origin = 'Trung Quốc', ingredients = 'Dây đeo làm từ sợi vải dù tơ mềm mại chống cọ xát tổn thương da cổ, khóa cài tháo nhanh bằng nhựa cứng, chuông đồng hình quả dâu tây.', benefits = 'Giúp định vị, nhận biết vị trí của thú cưng dễ dàng nhờ tiếng chuông leng keng vui tai mỗi khi bé di chuyển. Làm điệu trang trí bắt mắt dễ thương cho bé cưng thêm phần nổi bật, có khoen kim loại để móc thêm thẻ tên hoặc dây dắt.', usage_instructions = 'Đeo vòng vào cổ thú cưng, điều chỉnh độ dài dây bằng khóa trượt sao cho vòng vừa khít cổ nhưng vẫn đảm bảo độ rộng thoải mái (đút vừa 2 ngón tay vào giữa vòng cổ và cổ bé). Bấm khóa cài nghe tiếng ''tạch'' để cố định.', specs = 'Chiều dài dây điều chỉnh linh hoạt từ 15-30cm, độ rộng dây 1cm, họa tiết quả dâu tây ngọt ngào', badge = null, stock = 85, rating = 4.4, review_count = 58 WHERE id = 'a0000000-0000-0000-0000-000000000037';
